def nth_weekend_day_from(day_num, n):
    d = day_num
    found = 0
    while True:
        if d % 7 in (5, 6):
            found += 1
            if found == n:
                return d
        d += 1

def count_weekend_to_weekday_transitions(start_day_num, end_day_num):
    count = 0
    for d in range(start_day_num, end_day_num):
        if d % 7 in (5, 6) and (d + 1) % 7 not in (5, 6):
            count += 1
    return count

def count_business_days(start_day_num, end_day_num, weekend_days):
    count = 0
    for d in range(start_day_num, end_day_num + 1):
        if d % 7 not in weekend_days:
            count += 1
    return count

def add_business_days(start_day_num, n, weekend_days):
    d = start_day_num
    count = 0
    while count < n:
        d += 1
        if d % 7 not in weekend_days:
            count += 1
    return d

def subtract_business_days(start_day_num, n, weekend_days):
    d = start_day_num
    count = 0
    while count < n:
        d -= 1
        if d % 7 not in weekend_days:
            count += 1
    return d

def next_business_day(day_num, weekend_days):
    d = day_num + 1
    while d % 7 in weekend_days:
        d += 1
    return d

def previous_business_day(day_num, weekend_days):
    d = day_num - 1
    while d % 7 in weekend_days:
        d -= 1
    return d

def nearest_business_day(day_num, weekend_days):
    d = day_num
    while d % 7 in weekend_days:
        d += 1
    return d

def count_non_business_days(start_day_num, end_day_num, weekend_days):
    count = 0
    for d in range(start_day_num, end_day_num + 1):
        if d % 7 in weekend_days:
            count += 1
    return count

def business_days_needed_for_target(start_day_num, target_day_num, weekend_days):
    count = 0
    for d in range(start_day_num + 1, target_day_num + 1):
        if d % 7 not in weekend_days:
            count += 1
    return count

def first_business_day_of_week(week_start_day_num, weekend_days):
    for d in range(week_start_day_num, week_start_day_num + 7):
        if d % 7 not in weekend_days:
            return d
    return None

def last_business_day_of_week(week_start_day_num, weekend_days):
    for d in range(week_start_day_num + 6, week_start_day_num - 1, -1):
        if d % 7 not in weekend_days:
            return d
    return None

def format_duration_words(total_minutes):
    h = total_minutes // 60
    m = total_minutes % 60
    parts = []
    if h > 0:
        parts.append(f"{h} hour" + ("" if h == 1 else "s"))
    if m > 0 or h == 0:
        parts.append(f"{m} minute" + ("" if m == 1 else "s"))
    return " ".join(parts)
